/* From Uiverse.io by guilhermeyohan - Tags: button */
.__UIV_SCOPE__ .beach-button {
  background-color: #fbc02d;
  border: none;
  border-radius: 5px;
  color: #333;
  cursor: pointer;
  display: flex;
  align-items: center;
  font-size: 18px;
  font-weight: bold;
  padding: 10px 20px;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .beach-button:hover {
  background-color: #ffe082;
}

.__UIV_SCOPE__ .beach-button svg {
  height: 20px;
  margin-right: 10px;
  width: 20px;
}
